<script setup>import{ref,onMounted}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import PageHeader from'../components/PageHeader.vue';import{queryEntity,updateEntity}from'../api/admin.js';const items=ref([]);async function load(){items.value=(await queryEntity('schemes')).data.items}onMounted(load);async function review(row,status){if(status==='已退回')await ElMessageBox.prompt('请输入退回原因','退回方案');await updateEntity('schemes',row.id,{status});ElMessage.success(status==='已通过'?'方案已通过':'方案已退回');load()}</script><template><div class="admin-page"><PageHeader title="方案审核" description="审核设计方案版本与客户需求的一致性"/><div class="work-surface"><div class="filter-bar"><el-select placeholder="全部状态" style="width:140px"><el-option label="待审核" value="待审核"/><el-option label="已通过" value="已通过"/></el-select><el-button type="primary" plain>查询</el-button></div><div class="table-wrap"><el-table :data="items"><el-table-column prop="id" label="方案编号" min-width="150"/><el-table-column prop="order" label="订单号" min-width="160"/><el-table-column prop="customer" label="客户" width="100"/><el-table-column prop="designer" label="设计师" width="100"/><el-table-column prop="version" label="版本" width="80"/><el-table-column prop="submittedAt" label="提交时间" width="160"/><el-table-column prop="status" label="状态" width="100"/><el-table-column label="操作" width="180" fixed="right"><template #default="{row}"><el-button link>预览</el-button><el-button link type="success" @click="review(row,'已通过')">通过</el-button><el-button link type="danger" @click="review(row,'已退回')">退回</el-button></template></el-table-column></el-table></div></div></div></template>
